PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,role TEXT NOT NULL);
INSERT OR IGNORE INTO profiles VALUES ('teacher','teacher'),('learner','learner');
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY,draft TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS versions(id INTEGER PRIMARY KEY,course INTEGER NOT NULL REFERENCES courses,outline TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roster(course INTEGER REFERENCES courses,learner TEXT REFERENCES profiles,PRIMARY KEY(course,learner));
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY,version INTEGER NOT NULL REFERENCES versions,unit_idx INTEGER NOT NULL,activity_idx INTEGER NOT NULL,learner TEXT NOT NULL REFERENCES profiles,due TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Assigned');
CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY,assignment INTEGER NOT NULL REFERENCES assignments,request TEXT NOT NULL,work TEXT NOT NULL,UNIQUE(assignment,request));
CREATE TABLE IF NOT EXISTS reviews(submission INTEGER PRIMARY KEY REFERENCES submissions,decision TEXT NOT NULL,feedback TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(course INTEGER PRIMARY KEY REFERENCES courses,context TEXT NOT NULL,summary TEXT NOT NULL,problem TEXT NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS proposal_requests(token TEXT PRIMARY KEY,packet TEXT NOT NULL,course INTEGER NOT NULL REFERENCES courses);
